// Reports as PDF files made on the server (Vercel function), so no browser adds its own header and footer (the page
// address, date and title) – Safari on iPhone / iPad always adds them when printing. The app sends the report's HTML;
// Chromium prints it with the report's own page size and margins, and with our footer: "Generated by <name> · <date> ·
// Page x of y" (the report's own footer is kept when it has one). Only signed-in users of the app may use it.
const chromium = require('@sparticuz/chromium');
const puppeteer = require('puppeteer-core');

const SUPABASE_URL = process.env.EXPO_PUBLIC_SUPABASE_URL || process.env.SUPABASE_URL;
const ANON = process.env.EXPO_PUBLIC_SUPABASE_ANON_KEY || process.env.SUPABASE_ANON_KEY;

const esc = (v) => String(v ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c]);

/** The signed-in user of the request (Supabase access token), else null */
async function userOf(req) {
  const token = String(req.headers.authorization || '').replace(/^Bearer\s+/i, '');
  if (!token || !SUPABASE_URL || !ANON) return null;
  const r = await fetch(`${SUPABASE_URL}/auth/v1/user`, { headers: { apikey: ANON, Authorization: `Bearer ${token}` } });
  return r.ok ? r.json() : null;
}

/** The PDF of a report's HTML. footer: the "Generated by …" text, drawn in the bottom margin when the report has no footer of its own */
async function render(html, o = {}) {
  const browser = await puppeteer.launch({
    executablePath: process.env.CHROME_PATH || (await chromium.executablePath()),
    args: process.env.CHROME_PATH ? ['--no-sandbox'] : chromium.args,
    headless: true,
  });
  try {
    const page = await browser.newPage();
    await page.setContent(html, { waitUntil: 'networkidle0', timeout: 25000 });
    await page.emulateMediaType('print');
    const own = /@bottom-(left|right|center)/.test(html);
    return await page.pdf({
      preferCSSPageSize: true,
      printBackground: true,
      landscape: !!o.landscape,
      format: o.paper === 'A3' ? 'A3' : 'A4',
      displayHeaderFooter: !own && !!o.footer,
      headerTemplate: '<span></span>',
      footerTemplate: `<div style="width:100%;font:8px Arial,Helvetica,sans-serif;color:#666;padding:0 12mm;display:flex;justify-content:space-between">
        <span>${esc(o.footer)}</span><span>Page <span class="pageNumber"></span> of <span class="totalPages"></span></span></div>`,
    });
  } finally {
    await browser.close();
  }
}

async function handler(req, res) {
  if (req.method !== 'POST') return res.status(405).json({ error: 'POST only' });
  try {
    if (!(await userOf(req))) return res.status(401).json({ error: 'Sign in first' });
    const body = typeof req.body === 'string' ? JSON.parse(req.body) : req.body || {};
    if (typeof body.html !== 'string' || !body.html.trim()) return res.status(400).json({ error: 'Nothing to print' });
    const pdf = await render(body.html, body);
    res.setHeader('Content-Type', 'application/pdf');
    res.setHeader('Cache-Control', 'no-store');
    return res.status(200).send(Buffer.from(pdf));
  } catch (e) {
    return res.status(500).json({ error: String((e && e.message) || e).slice(0, 300) });
  }
}

module.exports = handler;
module.exports.render = render;
